#!/bin/sh
# Send a worker only the files that changed since they were last sent. On Wi-Fi, re-sending every mesh before every
# build costs minutes; this keeps each sent file's size and modification time in a small list and skips what matches.
#
#   sync_changed.sh <list.tsv> <user@host> <folder on the worker> <files...>
#   FORCE=1 sync_changed.sh ...        send everything
#
# The remote folder must exist. Forward slashes work for Windows paths over OpenSSH (D:/work/meshes).
# Do not edit this file, or any wrapper that calls it, while a run is going: a shell reads a script as it runs.
set -eu
list=$1; host=$2; dst=$3; shift 3
touch "$list"; sent=0
sig() { if stat -f '%z %m' "$1" >/dev/null 2>&1; then stat -f '%z %m' "$1"; else stat -c '%s %Y' "$1"; fi; }
for f in "$@"; do
  [ -f "$f" ] || continue
  s=$(sig "$f"); key="$host:$dst/$(basename "$f")"
  if [ -z "${FORCE:-}" ]; then
    last=$(awk -F'\t' -v k="$key" '$2==k{s=$1} END{print s}' "$list")
    [ "$last" = "$s" ] && continue
  fi
  scp -q "$f" "${host}:${dst}/" || { echo "failed: $f" >&2; exit 1; }
  printf '%s\t%s\n' "$s" "$key" >> "$list"; sent=$((sent + 1))
done
echo "sent $sent file(s) to ${host}:${dst}"
